SELECT CASE WHEN rating >= 4.4 THEN 'high' WHEN rating >= 1.5 THEN 'mid' ELSE 'low' END rating_bucket, city, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(country))) country_values, SORT_ARRAY(COLLECT_SET(country)) country_list, COUNT(rating) rating_count FROM suppliers GROUP BY CASE WHEN rating >= 4.4 THEN 'high' WHEN rating >= 1.5 THEN 'mid' ELSE 'low' END, city HAVING rating_count > 3 ORDER BY rating_bucket, city LIMIT 3;
